import type { ArchivedItem, Item, Maker } from '../types'
import { asset } from '../lib/asset'
import { byId } from '../lib/byId'
import antiques from './items.json'
import modern from './modern.json'
import retired from './retired.json'

/**
 * The catalog: antiques from the Met (generated by scripts/assets/catalog.py) and newly forged
 * pieces from named makers (generated by scripts/assets/modern.py), cheapest first, with image
 * paths resolved against the build base.
 */
// Hosts that cap the number of files (the claude.ai artifact build) skip the thumbnails;
// lists then load the full image.
const thumbs = !import.meta.env.VITE_NO_THUMBS

export const ITEMS: Item[] = [...(antiques as Item[]), ...(modern.items as Item[])]
  .sort((a, b) => a.value - b.value)
  .map((i) => ({ ...i, image: asset(i.image), thumb: thumbs && i.thumb ? asset(i.thumb) : undefined }))

export const ITEM_BY_ID = byId(ITEMS)

/** Pieces that have left the catalog. Saved pulls of them keep their name and record. */
export const ARCHIVE_BY_ID = byId(retired as ArchivedItem[])

/** Makers of the newly forged pieces in the chests. */
export const MAKERS: Maker[] = modern.makers as Maker[]
